begin;
do $$
declare u uuid:=gen_random_uuid(); other_u uuid:=gen_random_uuid(); app uuid; foreign_app uuid; d uuid; foreign_d uuid;
 h text:=md5(gen_random_uuid()::text)||md5(gen_random_uuid()::text); j text:='parity-'||gen_random_uuid()::text; result jsonb; v bigint;
 settings jsonb:='{"cadence":"weekly","timezone":"America/New_York","digestHour":9,"digestDay":1,"urgentDeadlineHours":24}'; token text;
begin
 if exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('read_quiet_mode','save_quiet_mode','reconsider_selection','save_preferences_preserving_quiet') and p.prosecdef) then raise exception 'Exposed parity RPC is SECURITY DEFINER'; end if;
 if has_function_privilege('anon','public.read_quiet_mode()','execute') or has_function_privilege('anon','public.save_quiet_mode(jsonb,bigint)','execute') or has_function_privilege('anon','public.reconsider_selection(uuid,text)','execute') or has_function_privilege('anon','public.save_preferences_preserving_quiet(jsonb,jsonb,text,jsonb)','execute') then raise exception 'Anonymous parity RPC access granted'; end if;
 if has_function_privilege('anon','private.read_quiet_mode_authenticated()','execute') or has_function_privilege('authenticated','private.reconsider_selection_owned(uuid,uuid,text)','execute') then raise exception 'Private boundary privilege leak'; end if;
 execute 'set local role anon';
 begin perform public.read_quiet_mode(); raise exception 'Anonymous quiet read allowed'; exception when insufficient_privilege then null; end;
 begin perform public.save_quiet_mode(settings,1); raise exception 'Anonymous quiet save allowed'; exception when insufficient_privilege then null; end;
 begin perform public.reconsider_selection(gen_random_uuid(),''); raise exception 'Anonymous reconsider allowed'; exception when insufficient_privilege then null; end;
 begin perform public.save_preferences_preserving_quiet('{}','[]',null,'{}'); raise exception 'Anonymous preferences save allowed'; exception when insufficient_privilege then null; end;
 execute 'reset role';
 insert into auth.users(id) values(u),(other_u);
 insert into public.jobs(id,canonical_url,employer) values(j,'https://example.com/parity','{}');
 insert into public.applications(user_id,job_id,draft) values(u,j,'{}') returning id into app;
 insert into public.applications(user_id,job_id,draft) values(other_u,j,'{}') returning id into foreign_app;
 insert into public.preferences(user_id,search) values(u,'{"excludedCompanies":["Example"],"autoSubmitApproved":false}');
 insert into public.selection_decisions(user_id,job_id,event_key,reason,preference,evidence,certainty,personal_version) values(u,j,'own','Reason','fit','Evidence','uncertain',1) returning id into d;
 insert into public.selection_decisions(user_id,job_id,event_key,reason,preference,evidence,certainty,personal_version) values(other_u,j,'foreign','Reason','fit','Evidence','uncertain',1) returning id into foreign_d;
 insert into private.agent_connections(user_id,name,token_hash,scopes,expires_at) values(u,'Parity',h,array['workspace:read','profile:write','activity:write'],now()+interval '1 hour');
 perform set_config('test.uid',u::text,true);
 execute 'set local role authenticated';
 result:=public.read_quiet_mode(); v:=(result->>'personalVersion')::bigint;
 result:=public.save_quiet_mode(settings,v);
 if result->'settings' is distinct from settings or (result->>'personalVersion')::bigint<=v then raise exception 'Human quiet write/version failed'; end if;
 if (select search->'excludedCompanies' from public.preferences where user_id=u)<>'["Example"]' then raise exception 'Quiet update erased unrelated preferences'; end if;
 perform public.save_preferences_preserving_quiet('{"locations":["NY"],"quietMode":{"cadence":"immediate"}}','[]',null,'{"pack":"base"}');
 if (select search->'quietMode' from public.preferences where user_id=u) is distinct from settings then raise exception 'Generic preference sync overwrote quiet'; end if;
 if (select search->'locations' from public.preferences where user_id=u)<>'["NY"]' then raise exception 'Unrelated preference merge failed'; end if;
 begin perform public.save_quiet_mode(settings,v); raise exception 'Stale human quiet write accepted'; exception when serialization_failure then null; end;

 begin perform public.reconsider_selection(foreign_d,''); raise exception 'Foreign human reconsider allowed'; exception when no_data_found then null; end;
 perform public.reconsider_selection(d,'');
 begin perform public.reconsider_selection(d,''); raise exception 'Stale human reconsider allowed'; exception when serialization_failure then null; end;
 execute 'reset role';
 token:=(select reconsidered_at::text from public.selection_decisions where id=d);
 result:=public.agent_dispatch(h,'selection.reconsider',jsonb_build_object('decisionId',d,'expectedReconsideredAt',token));
 if result->>'reconsidered_at' is null then raise exception 'Agent reconsider failed'; end if;
 begin perform public.agent_dispatch(h,'selection.reconsider',jsonb_build_object('decisionId',foreign_d,'expectedReconsideredAt','')); raise exception 'Foreign agent reconsider allowed'; exception when no_data_found then null; end;
 result:=public.agent_dispatch(h,'quiet.read','{}'); v:=(result->>'personalVersion')::bigint;
 result:=public.agent_dispatch(h,'quiet.update',jsonb_build_object('settings',settings||'{"cadence":"daily"}','expectedPersonalVersion',v));
 if result->'settings'->>'cadence'<>'daily' then raise exception 'Agent quiet save failed'; end if;
 begin perform public.agent_dispatch(h,'quiet.update',jsonb_build_object('settings',settings,'expectedPersonalVersion',v)); raise exception 'Stale agent quiet accepted'; exception when serialization_failure then null; end;
 v:=(result->>'personalVersion')::bigint;
 begin perform public.agent_dispatch(h,'quiet.update',jsonb_build_object('settings',settings||'{"autoSubmitApproved":true}','expectedPersonalVersion',v)); raise exception 'Quiet tool wrote unrelated setting'; exception when invalid_parameter_value then null; end;
 result:=public.agent_dispatch(h,'applications.human_action',jsonb_build_object('applicationId',app,'action','approve'));
 if result->>'performed'<>'false' or result->>'humanOnly'<>'true' or result->>'boardUrl' <> 'https://wcia013twe.github.io/codex-automated-job-board/applications/?application='||app then raise exception 'Approval boundary failed'; end if;
 if exists(select 1 from public.approvals where application_id=app) then raise exception 'Boundary forged approval'; end if;
 begin perform public.agent_dispatch(h,'applications.human_action',jsonb_build_object('applicationId',foreign_app,'action','approve')); raise exception 'Boundary leaked foreign link'; exception when no_data_found then null; end;
 update private.agent_connections set scopes=array['workspace:read'] where token_hash=h;
 begin perform public.agent_dispatch(h,'quiet.update',jsonb_build_object('settings',settings,'expectedPersonalVersion',v)); raise exception 'Quiet write scope bypass'; exception when insufficient_privilege then null; end;
 begin perform public.agent_dispatch(h,'selection.reconsider',jsonb_build_object('decisionId',d,'expectedReconsideredAt','')); raise exception 'Reconsider scope bypass'; exception when insufficient_privilege then null; end;
 update private.agent_connections set revoked_at=now() where token_hash=h;
 begin perform public.agent_dispatch(h,'quiet.read','{}'); raise exception 'Quiet revocation bypass'; exception when invalid_authorization_specification then null; end;
 if has_function_privilege('authenticated','private.quiet_mode_owned(uuid,jsonb,bigint)','execute') then raise exception 'Browser may supply arbitrary quiet owner'; end if;
end $$;
rollback;
